def is_valid_email(s: str) -> bool:
    if " " in s:
        return False
    if s.count("@") != 1:
        return False
    local, domain = s.split("@")
    if local == "":
        return False
    if "." not in domain:
        return False
    if domain.startswith(".") or domain.endswith("."):
        return False
    if ".." in domain:
        return False
    return True
